from __future__ import annotations

import os
import subprocess
import sys
from pathlib import Path
from typing import TYPE_CHECKING, Any

if TYPE_CHECKING:
    from thirdparty.internal.model.recipe import RecipeBase


class CMakeToolchain:
    """Generates a CMake toolchain file used by CMake.configure()."""

    def __init__(self, recipe: RecipeBase, generator: str | None = "Ninja") -> None:
        self._recipe = recipe
        self.generator: str | None = generator
        self.variables: dict[str, Any] = {}
        self.cache_variables: dict[str, Any] = {}
        self.preprocessor_definitions: dict[str, Any] = {}

    def generate(self) -> None:
        lines: list[str] = ["# Generated by ThirdParty CMakeToolchain\n"]
        if self.generator:
            lines.append(f"# generator: {self.generator}\n")

        # CMake 4.x removed support for cmake_minimum_required VERSION < 3.5;
        # set this policy variable so old projects don't error out.
        lines.append('set(CMAKE_POLICY_VERSION_MINIMUM "3.5" CACHE STRING "" FORCE)\n')

        # Disable ccache auto-detection: on Windows, ccache may be installed at
        # a path with spaces (e.g. C:/Program Files/...) which breaks cmd.exe
        # invocations generated by the Ninja/MSVC build system.
        lines.append('set(CMAKE_C_COMPILER_LAUNCHER "" CACHE STRING "" FORCE)\n')
        lines.append('set(CMAKE_CXX_COMPILER_LAUNCHER "" CACHE STRING "" FORCE)\n')

        # Forbid any recipe from downloading external code at configure/build time.
        # FetchContent_Populate/MakeAvailable will fail immediately if the source
        # dir is not already present, making network-dependent builds reproducible.
        lines.append('set(FETCHCONTENT_FULLY_DISCONNECTED ON CACHE BOOL "" FORCE)\n')

        if self._recipe.dep_package_paths:
            paths = ";".join(p.replace("\\", "/") for p in self._recipe.dep_package_paths)
            lines.append(f'set(CMAKE_PREFIX_PATH "{paths}" CACHE STRING "" FORCE)\n')

        for key, value in self.cache_variables.items():
            cmake_type, cmake_value = _to_cmake(value)
            cmake_value = cmake_value.replace("\\", "/")
            lines.append(f'set({key} "{cmake_value}" CACHE {cmake_type} "" FORCE)\n')

        for key, value in self.variables.items():
            cmake_type, cmake_value = _to_cmake(value)
            cmake_value = cmake_value.replace("\\", "/")
            lines.append(f'set({key} "{cmake_value}" CACHE {cmake_type} "" FORCE)\n')

        if self.preprocessor_definitions:
            defs = " ".join(
                f"{k}={v}" if not isinstance(v, bool) and v != 1 else k
                for k, v in self.preprocessor_definitions.items()
            )
            lines.append(f"add_compile_definitions({defs})\n")

        toolchain_path = Path(self._recipe.build_folder) / "thirdparty_toolchain.cmake"
        toolchain_path.parent.mkdir(parents=True, exist_ok=True)
        toolchain_path.write_text("".join(lines), encoding="utf-8")


class CMakeDeps:
    """Generates cmake config files for dependencies from their cpp_info declarations.

    For each dependency that declares ``cpp_info.libs`` (or an explicit
    ``cmake_target_name`` property), a pair of
    ``<Name>Config.cmake`` + ``<Name>ConfigVersion.cmake`` files is written into
    ``build_folder/cmake_deps/lib/cmake/<Name>/``.

    After generating the config files, ``CMAKE_FIND_PACKAGE_PREFER_CONFIG`` is
    enabled and ``<Name>_DIR`` cache hints are appended to the toolchain file so
    that cmake's ``find_package()`` calls resolve to our generated configs instead
    of the built-in Find modules (e.g. ``FindZLIB.cmake``).
    """

    def __init__(self, recipe: RecipeBase) -> None:
        self._recipe = recipe

    def set_property(self, *args: Any, **kwargs: Any) -> None:
        pass  # Conan-compatible stub; properties are set on cpp_info directly

    def generate(self) -> None:
        recipe = self._recipe
        build_dir = Path(recipe.build_folder)
        cmake_deps_dir = build_dir / "cmake_deps"

        dir_hints: dict[str, str] = {}  # cmake_file_name -> absolute config dir path

        for dep_name, dep_info in recipe.dependencies.items():
            cpp_info = dep_info.cpp_info

            cmake_target_name: str | None = cpp_info.get_property("cmake_target_name")
            cmake_file_name: str = cpp_info.get_property("cmake_file_name") or dep_name

            # Only generate a config file when the recipe explicitly declares
            # what it provides (libs or a named cmake target).
            if not cpp_info.libs and cmake_target_name is None:
                continue

            if cmake_target_name is None:
                cmake_target_name = f"{cmake_file_name}::{cmake_file_name}"

            pkg_folder = dep_info.package_folder
            version = dep_info.version or "0.0.0"

            # Resolve absolute include dirs that actually exist.
            include_dirs = [
                os.path.join(pkg_folder, d).replace("\\", "/")
                for d in cpp_info.includedirs
                if os.path.isdir(os.path.join(pkg_folder, d))
            ]

            # Find the first matching static library file.
            lib_path: str | None = None
            if cpp_info.libs:
                lib_path = _find_lib(pkg_folder, cpp_info.libdirs, cpp_info.libs[0])

            # ------------------------------------------------------------------
            # Build Config file content
            # ------------------------------------------------------------------
            lines: list[str] = []
            lines.append(f"# Generated by ThirdParty CMakeDeps for {dep_name}\n")

            # Optional: include the package's own cmake config first so its
            # targets (e.g. MINIZIP::minizip-ng) are available as deps.
            cmake_package_file: str | None = cpp_info.get_property("cmake_package_file")
            if cmake_package_file:
                abs_pkg_file = os.path.join(pkg_folder, cmake_package_file).replace("\\", "/")
                lines.append(f'include("{abs_pkg_file}" OPTIONAL)\n')
                lines.append("\n")

            lines.append(f'set({cmake_file_name}_VERSION "{version}")\n')
            lines.append(f'set({cmake_file_name}_FOUND TRUE)\n')

            # Old-style compatibility variables — many projects still use
            # ${FOO_INCLUDE_DIRS} / ${FOO_LIBRARIES} instead of imported targets.
            if include_dirs:
                include_dirs_str = ";".join(include_dirs)
                lines.append(f'set({cmake_file_name}_INCLUDE_DIR "{include_dirs_str}")\n')
                lines.append(f'set({cmake_file_name}_INCLUDE_DIRS "{include_dirs_str}")\n')
            if lib_path:
                lines.append(f'set({cmake_file_name}_LIBRARY "{lib_path}")\n')
                lines.append(f'set({cmake_file_name}_LIBRARIES "{lib_path}")\n')

            lines.append("\n")
            lines.append(f"if(NOT TARGET {cmake_target_name})\n")

            if lib_path:
                lines.append(f"  add_library({cmake_target_name} STATIC IMPORTED GLOBAL)\n")
                lines.append(f"  set_target_properties({cmake_target_name} PROPERTIES\n")
                lines.append(f'    IMPORTED_LOCATION "{lib_path}"\n')
                if include_dirs:
                    lines.append(
                        f'    INTERFACE_INCLUDE_DIRECTORIES "{";".join(include_dirs)}"\n'
                    )
                if cpp_info.defines:
                    lines.append(
                        f'    INTERFACE_COMPILE_DEFINITIONS "{";".join(cpp_info.defines)}"\n'
                    )
                if cpp_info.requires:
                    lines.append(
                        f'    INTERFACE_LINK_LIBRARIES "{";".join(cpp_info.requires)}"\n'
                    )
                lines.append("  )\n")
            else:
                # Header-only or wrapping another target → INTERFACE imported library.
                lines.append(f"  add_library({cmake_target_name} INTERFACE IMPORTED GLOBAL)\n")
                props: list[str] = []
                if include_dirs:
                    props.append(f'    INTERFACE_INCLUDE_DIRECTORIES "{";".join(include_dirs)}"')
                if cpp_info.defines:
                    props.append(
                        f'    INTERFACE_COMPILE_DEFINITIONS "{";".join(cpp_info.defines)}"'
                    )
                if cpp_info.requires:
                    props.append(
                        f'    INTERFACE_LINK_LIBRARIES "{";".join(cpp_info.requires)}"'
                    )
                if props:
                    lines.append(f"  set_target_properties({cmake_target_name} PROPERTIES\n")
                    lines.extend(f"{p}\n" for p in props)
                    lines.append("  )\n")

            lines.append("endif()\n")

            # Write the config file.
            config_dir = cmake_deps_dir / "lib" / "cmake" / cmake_file_name
            config_dir.mkdir(parents=True, exist_ok=True)

            (config_dir / f"{cmake_file_name}Config.cmake").write_text(
                "".join(lines), encoding="utf-8"
            )

            # Write a version file so cmake 4.x doesn't reject it when the
            # consumer requests a minimum version via find_package(Name X.Y.Z).
            version_content = (
                f'set(PACKAGE_VERSION "{version}")\n'
                'if(PACKAGE_FIND_VERSION VERSION_GREATER "${PACKAGE_VERSION}")\n'
                '  set(PACKAGE_VERSION_UNSUITABLE TRUE)\n'
                'else()\n'
                '  set(PACKAGE_VERSION_COMPATIBLE TRUE)\n'
                '  if(PACKAGE_FIND_VERSION VERSION_EQUAL "${PACKAGE_VERSION}")\n'
                '    set(PACKAGE_VERSION_EXACT TRUE)\n'
                '  endif()\n'
                'endif()\n'
            )
            (config_dir / f"{cmake_file_name}ConfigVersion.cmake").write_text(
                version_content, encoding="utf-8"
            )

            dir_hints[cmake_file_name] = str(config_dir).replace("\\", "/")

        if not dir_hints:
            return

        # Append CMAKE_FIND_PACKAGE_PREFER_CONFIG and per-package _DIR hints to
        # the toolchain file.  cmake reads the toolchain at configure-time (after
        # both tc.generate() and deps.generate() have run), so appending here is
        # safe even though tc.generate() wrote the file first.
        toolchain_path = build_dir / "thirdparty_toolchain.cmake"
        if toolchain_path.exists():
            extra: list[str] = ["\n# CMakeDeps: prefer Config-mode and set _DIR hints\n"]
            extra.append('set(CMAKE_FIND_PACKAGE_PREFER_CONFIG ON CACHE BOOL "" FORCE)\n')
            for file_name, config_dir_str in dir_hints.items():
                extra.append(
                    f'set({file_name}_DIR "{config_dir_str}" CACHE PATH "" FORCE)\n'
                )
            with toolchain_path.open("a", encoding="utf-8") as fh:
                fh.writelines(extra)


class CMake:
    """Wraps cmake subprocess calls for configure / build / install."""

    def __init__(self, recipe: RecipeBase) -> None:
        self._recipe = recipe

    def configure(
        self,
        variables: dict[str, Any] | None = None,
        build_script_folder: str | None = None,
    ) -> None:
        src = build_script_folder or self._recipe.source_folder
        toolchain = Path(self._recipe.build_folder) / "thirdparty_toolchain.cmake"

        cmd: list[str] = ["cmake", src, "--fresh"]

        generator = _read_generator(Path(self._recipe.build_folder))
        if generator:
            cmd += ["-G", generator]

        if toolchain.exists():
            cmd += [f"-DCMAKE_TOOLCHAIN_FILE={toolchain}"]
        # Must be a command-line -D arg, not in the toolchain file, because
        # cmake_minimum_required() is evaluated before the toolchain is read.
        cmd += ["-DCMAKE_POLICY_VERSION_MINIMUM=3.5"]
        cmd += [
            f"-DCMAKE_BUILD_TYPE={self._recipe.build_type}",
            f"-DCMAKE_INSTALL_PREFIX={self._recipe.package_folder}",
        ]

        if variables:
            for key, value in variables.items():
                _, cmake_value = _to_cmake(value)
                cmd += [f"-D{key}={cmake_value}"]

        Path(self._recipe.build_folder).mkdir(parents=True, exist_ok=True)
        env = _msvc_env() if generator and "Ninja" in generator else None
        _run(cmd, cwd=self._recipe.build_folder, env=env)

    def build(self, target: str | None = None, build_type: str | None = None) -> None:
        bt = build_type or self._recipe.build_type
        cmd = [
            "cmake", "--build", ".",
            "--config", bt,
            "--parallel", str(os.cpu_count() or 1),
        ]
        if target:
            cmd += ["--target", target]
        # Re-use the same env so Ninja/MSVC can find Windows SDK libs during compile.
        generator = _read_generator(Path(self._recipe.build_folder))
        env = _msvc_env() if generator and "Ninja" in generator else None
        _run(cmd, cwd=self._recipe.build_folder, env=env)

    def install(self, build_type: str | None = None) -> None:
        bt = build_type or self._recipe.build_type
        _run(["cmake", "--install", ".", "--config", bt], cwd=self._recipe.build_folder)


# ---------------------------------------------------------------------------
# Helpers
# ---------------------------------------------------------------------------

def _find_lib(pkg_folder: str, libdirs: list[str], libname: str) -> str | None:
    """Return the absolute path to the first matching static library for *libname*.

    Searches each directory in *libdirs* (relative to *pkg_folder*) trying
    platform-appropriate filename conventions (with/without ``lib`` prefix,
    ``.lib`` on Windows, ``.a`` on POSIX).
    """
    if sys.platform == "win32":
        # Prefer .lib but some build systems (Meson) produce .a even on Windows
        candidates = [
            (libname, ".lib"),
            (f"lib{libname}", ".lib"),
            (f"lib{libname}", ".a"),
            (libname, ".a"),
        ]
    else:
        candidates = [
            (f"lib{libname}", ".a"),
            (libname, ".a"),
            (f"lib{libname}", ".so"),
            (libname, ".so"),
        ]
    for libdir in libdirs:
        abs_libdir = os.path.join(pkg_folder, libdir)
        if not os.path.isdir(abs_libdir):
            continue
        for stem, ext in candidates:
            candidate = os.path.join(abs_libdir, f"{stem}{ext}")
            if os.path.exists(candidate):
                return candidate.replace("\\", "/")
    return None


def _to_cmake(value: Any) -> tuple[str, str]:
    if isinstance(value, bool):
        return "BOOL", "ON" if value else "OFF"
    return "STRING", str(value)


def _read_generator(build_dir: Path) -> str | None:
    """Return the generator name recorded in the toolchain file, or None."""
    tc = build_dir / "thirdparty_toolchain.cmake"
    if not tc.exists():
        return None
    for line in tc.read_text(encoding="utf-8").splitlines():
        if line.startswith("# generator:"):
            return line.split(":", 1)[1].strip()
    return None


def _msvc_env() -> dict[str, str] | None:
    """Source vcvarsall.bat x64 and return the resulting environment.

    Returns None when vcvarsall cannot be found (non-MSVC / non-Windows).
    Needed for Ninja generator which does not run vcvarsall automatically,
    so the linker can locate kernel32.lib and other Windows SDK libraries.
    Derives the vcvarsall path from the same cl.exe glob used by recipes so
    the correct VS installation is always selected.
    """
    import glob as _glob

    # Find cl.exe, sorted by MSVC toolchain version (newest last).
    cl_paths = _glob.glob(
        r"C:\Program Files\Microsoft Visual Studio\*\*\VC\Tools\MSVC\*\bin\Hostx64\x64\cl.exe"
    )
    if not cl_paths:
        return None

    def _msvc_ver(p: str) -> tuple[int, ...]:
        try:
            return tuple(int(x) for x in p.split("MSVC\\")[1].split("\\")[0].split("."))
        except Exception:
            return (0,)

    cl_paths.sort(key=_msvc_ver)
    cl_exe = cl_paths[-1]  # newest

    # vcvarsall.bat sits at <VS_root>\VC\Auxiliary\Build\vcvarsall.bat
    vc_dir = cl_exe.split("VC\\Tools")[0] + "VC"
    vcvarsall = os.path.join(vc_dir, "Auxiliary", "Build", "vcvarsall.bat")
    if not os.path.exists(vcvarsall):
        return None

    result = subprocess.run(
        f'call "{vcvarsall}" x64 && set',
        shell=True, capture_output=True, text=True,
    )
    if result.returncode != 0:
        return None

    env: dict[str, str] = dict(os.environ)
    for line in result.stdout.splitlines():
        if "=" in line:
            k, v = line.split("=", 1)
            # Windows env vars are case-insensitive; deduplicate so that e.g.
            # vcvarsall's 'Path' and os.environ's 'PATH' don't coexist as two
            # separate keys (which would make the child see two PATH entries
            # and use the un-cleaned one).
            existing = next((ek for ek in env if ek.upper() == k.upper()), None)
            if existing:
                del env[existing]
            env[k] = v

    # Strip directories containing ccache from PATH.  On Windows, ccache is
    # often installed under "C:\Program Files\..." (a path with spaces).
    # Some projects (e.g. assimp) use RULE_LAUNCH_LINK which embeds the
    # ccache path unquoted inside a cmd.exe /C "..." invocation, breaking
    # the link step.  Removing ccache from PATH prevents cmake's find_program()
    # from detecting it so the rule is never generated.
    path_key = next((k for k in env if k.upper() == "PATH"), None)
    if path_key:
        clean_dirs = [
            d for d in env[path_key].split(";")
            if not os.path.exists(os.path.join(d, "ccache.exe"))
        ]
        env[path_key] = ";".join(clean_dirs)

    return env


def _run(cmd: list[str], cwd: str, env: dict[str, str] | None = None) -> None:
    result = subprocess.run(cmd, cwd=cwd, env=env, check=False)
    if result.returncode != 0:
        raise RuntimeError(
            f"cmake command failed (exit {result.returncode}):\n  {' '.join(cmd)}"
        )
